teams_data = run_query(q_teams)
team_nodes = teams_data.get('teams', {}).get('nodes', [])
team_id = None
for t in team_nodes:
    if t.get('name', '').lower() == 'engineering':
        team_id = t['id']
        break
if not team_id:
    raise SystemExit('Team "Engineering" not found. Please ensure the team exists.')

