labels_data = run_query(q_labels)
label_nodes = labels_data.get('labels', {}).get('nodes', [])
labels_needed = { 'UX': None, 'Urgent': None }
for l in label_nodes:
    name = l.get('name')
    if name in labels_needed:
        labels_needed[name] = l['id']

