url = 'https://api.linear.app/graphql'
headers = {'Content-Type': 'application/json'}

# Helper to send a query
def gql(query, variables=None):
    payload = {'query': query}
    if variables is not None:
        payload['variables'] = variables
    resp = requests.post(url, headers=headers, data=json.dumps(payload))
    try:
        return resp.status_code, resp.json()
    except Exception:
        return resp.status_code, resp.text

# 1) find Product team id
q_team = '''query { teams(filter: { name: { eq: "Product" } }) { nodes { id name } } }'''
status, res = gql(q_team)
print('status', status)
print(json.dumps(res, indent=2))

# If not found, list all teams
if 'data' in res and res.get('data', {}).get('teams', {}).get('nodes'):
    team_nodes = res['data']['teams']['nodes']
    if len(team_nodes) > 0:
        team_id = team_nodes[0]['id']
        print('Product team id:', team_id)
    else:
        print('No team named Product found')
        team_id = None
else:
    print('teams query error or no result')
    team_id = None

# 2) try various issues queries to find ones mentioning 'trace analysis'
queries = []
if team_id:
    queries.append(('filter_title_contains', '''query($teamId: String!) { issues(filter: { teamId: { eq: $teamId }, title: { contains: "trace analysis" } }, first: 50) { nodes { id title createdAt updatedAt url } } }'''))
    queries.append(('filter_title_contains_insensitive', '''query($teamId: String!) { issues(filter: { teamId: { eq: $teamId }, title: { containsInsensitive: "trace analysis" } }, first: 50) { nodes { id title createdAt updatedAt url } } }'''))
    queries.append(('search_query', '''query($q: String!, $teamId: String!) { issues(query: $q, filter: { teamId: { eq: $teamId } }, first: 50) { nodes { id title createdAt updatedAt url } } }'''))
    queries.append(('description_contains', '''query($teamId: String!) { issues(filter: { teamId: { eq: $teamId }, description: { containsInsensitive: "trace analysis" } }, first: 50) { nodes { id title createdAt updatedAt url } } }'''))
else:
    queries.append(('all_issues_search', '''query { issues(query: "trace analysis", first: 50) { nodes { id title createdAt updatedAt url team { id name } } } }'''))

results = {}
for name, q in queries:
    vars = {'teamId': team_id, 'q': 'trace analysis'} if team_id else None
    status, res = gql(q, vars)
    print('\n---', name, 'status', status)
    print(json.dumps(res, indent=2))
    results[name] = res

# Output collected results
print('\nDONE')
