import json

API_URL = 'https://api.linear.app/graphql'
HEADERS = {
    'Content-Type': 'application/json',
    # Authentication handled via proxy; placeholder token shown here
    'Authorization': 'Bearer PLACEHOLDER_TOKEN'
}

def gql(query, variables=None):
    payload = {'query': query}
    if variables is not None:
        payload['variables'] = variables
    r = requests.post(API_URL, headers=HEADERS, json=payload)
    try:
        data = r.json()
    except Exception as e:
        raise SystemExit(f'Non-JSON response: {r.text}')
    if 'errors' in data:
        raise SystemExit(f"GraphQL errors: {data['errors']}")
    return data['data']

# 1) Find all labels named 'RL'
query_labels = '''
query($name: String!) {
  labels(filter: {name: {eq: $name}}, first: 100) {
    nodes {
      id
      name
      team {
        id
        key
        name
      }
    }
  }
}
'''
res = gql(query_labels, {'name': 'RL'})
rl_labels = res['labels']['nodes']
print(f"Found {len(rl_labels)} 'RL' label(s)")

results = []

for rl in rl_labels:
    team = rl['team']
    team_id = team['id'] if team else None
    team_key = team.get('key') if team else None
    team_name = team.get('name') if team else None
    print(f"Processing RL label id={rl['id']} team={team_key or team_name}")

    # 2) Check if 'AI' label exists for this team
    query_ai = '''
    query($name: String!, $teamId: String) {
      labels(filter: {name: {eq: $name}, teamId: {eq: $teamId}}, first: 10) {
        nodes { id name team { id key name } }
      }
    }
    '''
    res_ai = gql(query_ai, {'name': 'AI', 'teamId': team_id})
    ai_nodes = res_ai['labels']['nodes']
    if ai_nodes:
        ai_label = ai_nodes[0]
        print(f"AI label already exists: {ai_label['id']}")
    else:
        # create AI label in same team
        mut_create = '''
        mutation($input: LabelCreateInput!) {
          labelCreate(input: $input) {
            success
            label { id name team { id key name } }
          }
        }
        '''
        input_obj = {'name': 'AI'}
        if team_id:
            input_obj['teamId'] = team_id
        res_create = gql(mut_create, {'input': input_obj})
        ai_label = res_create['labelCreate']['label']
        print(f"Created AI label: {ai_label['id']}")

    ai_label_id = ai_label['id']

    # 3) Iterate issues on the RL label (paginated)
    issues = []
    after = None
    query_issues = '''
    query($id: String!, $after: String) {
      label(id: $id) {
        id
        name
        issues(first: 100, after: $after) {
          nodes { id title labels { nodes { id name } } }
          pageInfo { hasNextPage endCursor }
        }
      }
    }
    '''
    while True:
        res_issues = gql(query_issues, {'id': rl['id'], 'after': after})
        label_data = res_issues.get('label')
        if not label_data:
            print(f"Label {rl['id']} not found when fetching issues")
            break
        batch = label_data['issues']['nodes']
        issues.extend(batch)
        page_info = label_data['issues']['pageInfo']
        if page_info['hasNextPage']:
            after = page_info['endCursor']
        else:
            break

    print(f"Found {len(issues)} issue(s) with RL label on team {team_key or team_name}")

    # 4) For each issue, set labels to include AI and exclude RL
    for issue in issues:
        issue_id = issue['id']
        current_label_ids = [lbl['id'] for lbl in issue['labels']['nodes']]
        if ai_label_id in current_label_ids and rl['id'] not in current_label_ids:
            print(f"Issue {issue_id} already has AI and not RL; skipping")
            results.append({'issue': issue_id, 'status': 'skipped'})
            continue
        new_label_ids = [lid for lid in current_label_ids if lid != rl['id']]
        if ai_label_id not in new_label_ids:
            new_label_ids.append(ai_label_id)

        mut_update = '''
        mutation($input: IssueUpdateInput!) {
          issueUpdate(input: $input) {
            success
            issue { id }
          }
        }
        '''
        input_obj = {'id': issue_id, 'labelIds': new_label_ids}
        res_update = gql(mut_update, {'input': input_obj})
        success = res_update['issueUpdate']['success']
        print(f"Updated issue {issue_id}: success={success}")
        results.append({'issue': issue_id, 'status': 'updated', 'new_label_ids': new_label_ids})

print('\nSummary:')
print(json.dumps(results, indent=2))
