API_URL = 'https://api.linear.app/graphql'
HEADERS = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer PLACEHOLDER_TOKEN'
}

def gql(query, variables=None):
    payload = {'query': query}
    if variables is not None:
        payload['variables'] = variables
    r = requests.post(API_URL, headers=HEADERS, json=payload)
    try:
        data = r.json()
    except Exception as e:
        raise SystemExit(f'Non-JSON response: {r.text}')
    if 'errors' in data:
        raise SystemExit(f"GraphQL errors: {data['errors']}")
    return data['data']

# 1) Find all issueLabels named 'RL'
query_rl = '''
query($name: String!) {
  issueLabels(filter: {name: {eq: $name}}, first: 100) {
    nodes { id name team { id key name } }
  }
}
'''
res = gql(query_rl, {'name': 'RL'})
rl_labels = res['issueLabels']['nodes']
print(f"Found {len(rl_labels)} RL label(s)")
if not rl_labels:
    print('No RL labels found. Exiting.')
    sys.exit(0)

summary = []

for rl in rl_labels:
    rl_id = rl['id']
    team = rl.get('team')
    team_id = team['id'] if team else None
    team_key = team['key'] if team else None
    team_name = team['name'] if team else None
    print(f"\nProcessing RL label {rl_id} (team={team_key or team_name or 'org-wide'})")

    # 2) Find or create AI label in same team
    # search
    query_ai_search = '''
    query($name: String!, $teamId: String) {
      issueLabels(filter: {name: {eq: $name}, team: {id: {eq: $teamId}}}, first: 10) {
        nodes { id name team { id key name } }
      }
    }
    '''
    ai_nodes = gql(query_ai_search, {'name': 'AI', 'teamId': team_id})['issueLabels']['nodes']
    if ai_nodes:
        ai_label = ai_nodes[0]
        print(f"Found existing AI label: {ai_label['id']}")
    else:
        # create
        mut_create = '''
        mutation($input: IssueLabelCreateInput!) {
          issueLabelCreate(input: $input) {
            success
            issueLabel { id name team { id key name } }
          }
        }
        '''
        input_obj = {'name': 'AI'}
        if team_id:
            input_obj['teamId'] = team_id
        res_create = gql(mut_create, {'input': input_obj})
        ai_label = res_create['issueLabelCreate']['issueLabel']
        print(f"Created AI label: {ai_label['id']}")

    ai_id = ai_label['id']

    # 3) Get all issues that have RL label (paginated)
    issues = []
    after = None
    query_issues = '''
    query($id: String!, $after: String) {
      issueLabel(id: $id) {
        id
        name
        issues(first: 100, after: $after) {
          nodes {
            id
            title
            labels { nodes { id name } }
          }
          pageInfo { hasNextPage endCursor }
        }
      }
    }
    '''
    while True:
        data = gql(query_issues, {'id': rl_id, 'after': after})
        label_data = data.get('issueLabel')
        if not label_data:
            print(f"Label {rl_id} not found when fetching issues")
            break
        batch = label_data['issues']['nodes']
        issues.extend(batch)
        page_info = label_data['issues']['pageInfo']
        if page_info['hasNextPage']:
            after = page_info['endCursor']
        else:
            break

    print(f"Found {len(issues)} issue(s) with RL")

    # 4) For each issue, add AI (if missing) and remove RL
    for issue in issues:
        issue_id = issue['id']
        issue_title = issue.get('title')
        current_labels = {lbl['name']: lbl['id'] for lbl in issue.get('labels', {}).get('nodes', [])}
        need_add = ai_id not in current_labels.values()
        need_remove = rl_id in current_labels.values()
        item = {'issue_id': issue_id, 'title': issue_title, 'added_ai': False, 'removed_rl': False}

        if need_add:
            mut_add = '''
            mutation($input: IssueAddLabelInput!) {
              issueAddLabel(input: $input) { success }
            }
            '''
            try:
                r = gql(mut_add, {'input': {'issueId': issue_id, 'labelId': ai_id}})
                item['added_ai'] = True
                print(f"Added AI to issue {issue_id}")
            except SystemExit as e:
                print(f"Failed to add AI to {issue_id}: {e}")

        else:
            print(f"Issue {issue_id} already has AI")

        if need_remove:
            mut_remove = '''
            mutation($input: IssueRemoveLabelInput!) {
              issueRemoveLabel(input: $input) { success }
            }
            '''
            try:
                r = gql(mut_remove, {'input': {'issueId': issue_id, 'labelId': rl_id}})
                item['removed_rl'] = True
                print(f"Removed RL from issue {issue_id}")
            except SystemExit as e:
                print(f"Failed to remove RL from {issue_id}: {e}")
        else:
            print(f"Issue {issue_id} does not have RL (unexpected)")

        summary.append(item)

